import itertools
def quad(r0,r1,c0,c1):
    return {(r,c) for r in range(r0,r1) for c in range(c0,c1) if G[r][c]==4}
def analyze(cells, name):
    deg = {}
    for (r,c) in cells:
        d = sum(((r+dr,c+dc) in cells) for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)))
        deg[(r,c)] = d
    from collections import Counter
    print(name, 'degrees:', Counter(deg.values()), 'ends:', [k for k,v in deg.items() if v==1])
    return deg
quads = {'TL': quad(0,5,0,7), 'TR': quad(0,5,8,20), 'BL': quad(6,20,0,7), 'BR': quad(6,20,8,20)}
for n,q in quads.items(): analyze(q,n)
# Try tracing BR as a path from an endpoint
def trace(cells, start):
    path=[start]; prev=None; cur=start
    while True:
        nbrs=[n for n in ((cur[0]+1,cur[1]),(cur[0]-1,cur[1]),(cur[0],cur[1]+1),(cur[0],cur[1]-1)) if n in cells and n!=prev]
        nxt=[n for n in nbrs if n not in path]
        if not nxt: break
        prev,cur=cur,nxt[0]; path.append(cur)
    return path
